#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, rev;
    long long cap;
    long long cst;
    Edge(int to, int rev, long long cap, long long cst) : to(to), rev(rev), cap(cap), cst(cst) {}
};

struct FlowNetwork {
    int size;
    std::vector<std::vector<Edge>> adj_list;
    std::vector<std::pair<int, int>> edges_list;
    std::vector<long long> potential;
    std::vector<int> prev_node, prev_edge;
    std::vector<bool> visited;

    FlowNetwork(int size) : size(size) {
        adj_list.resize(size);
        potential.resize(size);
        prev_node.resize(size);
        prev_edge.resize(size);
        visited.resize(size);
    }

    int add_edge(int u, int v, long long capacity, long long cost) {
        int idx = (int)edges_list.size();
        edges_list.emplace_back(u, (int)adj_list[u].size());
        adj_list[u].emplace_back(v, (int)adj_list[v].size(), capacity, cost);
        adj_list[v].emplace_back(u, (int)adj_list[u].size() - 1, 0, -cost);
        return idx;
    }

    Edge get_edge(int i) {
        auto &e = adj_list[edges_list[i].first][edges_list[i].second];
        auto &re = adj_list[e.to][e.rev];
        return Edge(edges_list[i].first, e.to, e.cap + re.cap, e.cst);
    }

    std::vector<Edge> all_edges() {
        std::vector<Edge> result;
        for (int i = 0; i < (int)edges_list.size(); ++i) {
            auto &e = adj_list[edges_list[i].first][edges_list[i].second];
            auto &re = adj_list[e.to][e.rev];
            result.emplace_back(edges_list[i].first, e.to, e.cap + re.cap, e.cst);
        }
        return result;
    }

    bool dijkstra(int s, int t) {
        std::fill(visited.begin(), visited.end(), false);
        std::vector<long long> dist(size, LLONG_MAX);
        dist[s] = 0;
        using pli = std::pair<long long, int>;
        std::priority_queue<pli, std::vector<pli>, std::greater<pli>> heap;
        heap.emplace(0, s);
        while (!heap.empty()) {
            auto [d, v] = heap.top(); heap.pop();
            if (visited[v]) continue;
            visited[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)adj_list[v].size(); ++i) {
                auto &e = adj_list[v][i];
                if (e.cap == 0 || visited[e.to]) continue;
                long long nd = d + e.cst;
                if (dist[e.to] > nd) {
                    dist[e.to] = nd;
                    prev_node[e.to] = v;
                    prev_edge[e.to] = i;
                    heap.emplace(nd, e.to);
                }
            }
        }
        if (!visited[t]) return false;
        for (int v = 0; v < size; ++v) {
            if (visited[v]) {
                potential[v] -= dist[t];
            }
        }
        return true;
    }

    std::vector<std::pair<long long, long long>> min_cost_max_flow(int s, int t, long long max_flow = (1LL << 32) - 1) {
        long long flow = 0;
        long long total_cost = 0;
        std::vector<std::pair<long long, long long>> results;
        results.emplace_back(flow, total_cost);
        while (flow < max_flow) {
            if (!dijkstra(s, t)) break;
            long long c = max_flow - flow;
            int v = t;
            while (v != s) {
                int u = prev_node[v];
                auto &e = adj_list[u][prev_edge[v]];
                c = std::min(c, e.cap);
                v = u;
            }
            v = t;
            while (v != s) {
                int u = prev_node[v];
                auto &e = adj_list[u][prev_edge[v]];
                e.cap -= c;
                adj_list[v][e.rev].cap += c;
                v = u;
            }
            long long delta = -potential[s];
            flow += c;
            total_cost += c * delta;
            if (results.back().second == total_cost) results.pop_back();
            results.emplace_back(flow, total_cost);
        }
        return results;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int a1, a2, a3;
    cin >> a1 >> a2 >> a3;
    int b1, b2, b3;
    cin >> b1 >> b2 >> b3;

    FlowNetwork g(8);
    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);

    for (int i = 1; i <= 3; ++i) {
        for (int j = 4; j <= 6; ++j) {
            long long cst = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, LLONG_MAX, cst);
        }
    }

    auto res = g.min_cost_max_flow(0, 7);
    long long ans1 = res.back().first;
    long long ans2 = std::min(a1, b2) + std::min(a2, b3) + std::min(a3, b1);
    cout << ans1 << " " << ans2 << "\n";
    return 0;
}

